"""Static, clearly labelled design review of Build D (not the running React app).
Metrics are computed from bundled synthetic example data, never invented.
The CSS is shared with the actual Build D canvas implementation.
"""
from pathlib import Path
from html import escape
import pandas as pd
base=Path(__file__).resolve().parents[1]
df=pd.read_csv(base/'examples/demo_property_prices.csv')
